let vxFlipped = false;
let vyFlipped = false;
for (const brick of state.bricks) {
  if (!brick.alive) continue;

  if (collides(state.ball, brick)) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);

    // Resolve collision: determine hit face by minimum penetration
    const dx1 = (brick.x + brick.w) - (state.ball.x - state.ball.r);
    const dx2 = (state.ball.x + state.ball.r) - brick.x;
    const dy1 = (brick.y + brick.h) - (state.ball.y - state.ball.r);
    const dy2 = (state.ball.y + state.ball.r) - brick.y;

    const min = Math.min(dx1, dx2, dy1, dy2);

    if (min === dx1) {
      if (!vxFlipped) {
        state.ball.vx = -Math.abs(state.ball.vx);
        vxFlipped = true;
      }
      state.ball.x += dx1;
    } else if (min === dx2) {
      if (!vxFlipped) {
        state.ball.vx = Math.abs(state.ball.vx);
        vxFlipped = true;
      }
      state.ball.x -= dx2;
    } else if (min === dy1) {
      if (!vyFlipped) {
        state.ball.vy = -Math.abs(state.ball.vy);
        vyFlipped = true;
      }
      state.ball.y += dy1;
    } else if (min === dy2) {
      if (!vyFlipped) {
        state.ball.vy = Math.abs(state.ball.vy);
        vyFlipped = true;
      }
      state.ball.y -= dy2;
    }
  }

  ctx.fillStyle = brickColor(brick.row);
  ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
}

